async def ui_investidor_criar(request: Request, session: SessionDep, user: UIAdmin) -> HTMLResponse:
    form = await request.form()
    nome = str(form.get("nome") or "").strip()
    if not nome:
        return templates.TemplateResponse(request, "_form_simples.html",
            _form_ctx_investidor(None, "Nome obrigatório"), status_code=400)
